static uint8_t g_chunk_buf[CHUNK_BUF_CAP];
static int g_loaded_chunk = -1;
static size_t g_loaded_len = 0;

int cases_load(int idx, Case911 *out) {
    if (!out || idx < 0 || idx >= TOTAL_CASES) return 0;
    int cid = idx / CHUNK_SIZE;
    int local = idx % CHUNK_SIZE;
    if (cid < 0 || cid >= NUM_CHUNKS) return 0;

    if (g_loaded_chunk != cid) {
        const ChunkMeta *cm = &g_chunk_meta[cid];
        int res = tiny_inflate_raw(g_cases_blob + cm->off, cm->comp_len,
                                   g_chunk_buf, sizeof(g_chunk_buf));
        if (res <= 0) {
            g_loaded_chunk = -1;
            g_loaded_len = 0;
            return 0;
        }
        g_loaded_chunk = cid;
        g_loaded_len = (size_t)res;
    }

    size_t pos = 0;
    for (int k = 0; k <= local; k++) {
        if (pos >= g_loaded_len) return 0;
        uint8_t ans = g_chunk_buf[pos++];
        const char *fields[12];
        for (int fi = 0; fi < 12; fi++) {
            if (pos >= g_loaded_len) return 0;
            fields[fi] = (const char *)(g_chunk_buf + pos);
            while (pos < g_loaded_len && g_chunk_buf[pos] != 0) pos++;
            if (pos >= g_loaded_len) return 0;
            pos++;
        }
        if (k == local) {
            out->ans      = (int)ans;
            out->cat      = fields[0];
            out->open_msg = fields[1];
            out->q1_good  = fields[2];
            out->q1_bad   = fields[3];
            out->r1_good  = fields[4];
            out->r1_bad   = fields[5];
            out->q2_good  = fields[6];
            out->q2_bad   = fields[7];
            out->r2_good  = fields[8];
            out->r2_bad   = fields[9];
            out->win_msg  = fields[10];
            out->lose_msg = fields[11];
            return 1;
        }
    }
    return 0;
}
